'use client';

import React, { useEffect, useState } from 'react';
import styles from './page.module.css';

interface Account {
  id: string;
  accountNumber: string;
  balance: number;
}

export default function Home() {
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // In a real app, this would be an API call to the backend
    // For now, we fetch from the backend if it's running
    fetch('http://localhost:8080/api/accounts')
      .then(res => res.json())
      .then(data => {
        setAccounts(data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Failed to fetch accounts", err);
        // Fallback dummy data if backend isn't up
        setAccounts([
          { id: '1', accountNumber: 'CHK-1234', balance: 5430.50 },
          { id: '2', accountNumber: 'SAV-5678', balance: 12000.00 }
        ]);
        setLoading(false);
      });
  }, []);

  return (
    <div className={styles.container}>
      <header className={styles.header}>
        <div className={styles.logo}>Bank Modern</div>
        <nav className={styles.nav}>
          <a href="#">Dashboard</a>
          <a href="#">Transfer</a>
          <a href="#">History</a>
        </nav>
      </header>

      <main className={styles.main}>
        <section className={styles.hero}>
          <h1>Welcome to Bank Modern</h1>
          <p>Your finances, elevated. A modern classic approach to banking.</p>
        </section>

        <section className={styles.dashboard}>
          {loading ? (
            <p>Loading accounts...</p>
          ) : (
            accounts.map((account) => (
              <div key={account.id} className={styles.card}>
                <div className={styles.cardTitle}>{account.accountNumber}</div>
                <div className={styles.cardValue}>${account.balance.toFixed(2)}</div>
                <button className={styles.actionButton}>View Details</button>
              </div>
            ))
          )}
        </section>
      </main>
    </div>
  );
}
